$event = ['id'=>0,'title'=>'','slug'=>'','event_date'=>'','start_time'=>'08:00:00','short_description'=>'','about'=>'','poster'=>null,'schedule_pdf'=>null,'registration_url'=>'','status'=>'draft','banner_active'=>0,'banner_label'=>'رویداد پیش‌رو','banner_cta'=>'مشاهده رویداد','banner_link'=>'','banner_theme'=>'teal','banner_dismissible'=>1,'banner_background'=>'#007b7a','banner_text_color'=>'#ffffff','banner_accent_color'=>'#f4a61e'];
$heroes = $people = $speakers = $partners = [];
if ($id) { $st=$pdo->prepare('SELECT * FROM events WHERE id=?'); $st->execute([$id]); $event=array_merge($event,$st->fetch() ?: []); $q=function(string $sql)use($pdo,$id){$s=$pdo->prepare($sql);$s->execute([$id]);return $s->fetchAll();}; $heroes=$q('SELECT * FROM event_heroes WHERE event_id=? ORDER BY sort_order,id'); $people=$q('SELECT * FROM event_people WHERE event_id=? ORDER BY sort_order,id'); $speakers=$q('SELECT * FROM event_speakers WHERE event_id=? ORDER BY sort_order,id'); $partners=$q('SELECT * FROM event_partners WHERE event_id=? ORDER BY sort_order,id'); }
